23	    end;
24	
25	    procedure CheckOut(ContractNo: Code[20])
26	    var
27	        Contract: Record "CGR Rental Contract";
28	        Vehicle: Record "CGR Vehicle";
29	        FleetMgt: Codeunit "CGR Fleet Mgt";
30	        CoreEvents: Codeunit "CGR Core Events";
31	    begin
32	        Contract.Get(ContractNo);
33	        if Contract.Status <> Contract.Status::Open then
34	            Error(WrongStatusErr, ContractNo, Contract.Status::Open);
35	        if FleetMgt.IsDueForService(Contract."Vehicle No.") then
36	            Error(DueForServiceErr, Contract."Vehicle No.");
