    [Test]
    procedure IsDueForServiceTrueAtOrAboveThreshold()
    var
        FleetMgt: Codeunit "CGR Fleet Mgt";
    begin
        // [GIVEN] Two Default-strategy vehicles with Last Service Km 5000, so the next
        // service km is 20000: one exactly at that mileage, one above it
        Lib.CreateVehicle('T-FLT-011', 20000, Enum::"CGR Maintenance Strategy"::Default);
        Lib.SetLastServiceKm('T-FLT-011', 5000);
        Lib.CreateVehicle('T-FLT-012', 20500, Enum::"CGR Maintenance Strategy"::Default);
        Lib.SetLastServiceKm('T-FLT-012', 5000);

        // [WHEN] Checking whether each vehicle is due for service
        // [THEN] Both are due, whether at or above the threshold
        Assert.IsTrue(FleetMgt.IsDueForService('T-FLT-011'), 'At the threshold is due for service');
        Assert.IsTrue(FleetMgt.IsDueForService('T-FLT-012'), 'Above the threshold is due for service');
    end;

    [Test]
    procedure IsDueForServiceFalseBelowThreshold()
    var
        FleetMgt: Codeunit "CGR Fleet Mgt";
    begin
        // [GIVEN] A Default-strategy vehicle with Last Service Km 5000 (next service km 20000)
        // and mileage one km short of that threshold
        Lib.CreateVehicle('T-FLT-013', 19999, Enum::"CGR Maintenance Strategy"::Default);
        Lib.SetLastServiceKm('T-FLT-013', 5000);

        // [WHEN] Checking whether the vehicle is due for service
        // [THEN] It is not due
        Assert.IsFalse(FleetMgt.IsDueForService('T-FLT-013'), 'Below the threshold is not due for service');
    end;

    [Test]
    procedure SuspendRentalsStillBlocksVehicleNotDueForService()
    var
        Setup: Record "CGR Setup";
        FleetMgt: Codeunit "CGR Fleet Mgt";
    begin
        // [GIVEN] A vehicle that is not due for service, and Suspend Rentals turned on
        Lib.CreateVehicle('T-FLT-014', 1000, Enum::"CGR Maintenance Strategy"::Default);
        Setup.GetOrCreate();
        Setup."Suspend Rentals" := true;
        Setup.Modify();

        // [WHEN] Checking whether the vehicle is available
        // [THEN] The existing Suspend Rentals subscriber still makes it unavailable
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-014'), 'Suspend Rentals still blocks a vehicle not due for service');
    end;

    [Test]
    procedure SuspendRentalsCannotMakeDueVehicleAvailable()
    var
        Setup: Record "CGR Setup";
        FleetMgt: Codeunit "CGR Fleet Mgt";
    begin
        // [GIVEN] A vehicle that is due for service, neither checked out nor blocked
        Lib.CreateVehicle('T-FLT-015', 15000, Enum::"CGR Maintenance Strategy"::Default);
        Setup.GetOrCreate();

        // [WHEN] Suspend Rentals is on
        Setup."Suspend Rentals" := true;
        Setup.Modify();
        // [THEN] The vehicle is still not available
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-015'), 'Due vehicle is not available when Suspend Rentals is true');

        // [WHEN] Suspend Rentals is off
        Setup."Suspend Rentals" := false;
        Setup.Modify();
        // [THEN] The vehicle is still not available: the subscriber cannot override a due vehicle
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-015'), 'Due vehicle is not available when Suspend Rentals is false');
    end;
}

