    [Test]
    procedure CheckOutDueForServiceVehicleFails()
    var
        RentalMgt: Codeunit "CGR Rental Mgt";
        ContractNo: Code[20];
    begin
        // [GIVEN] An open contract for a vehicle that has reached its Default strategy's
        // next service km (Last Service Km 0 + 15000)
        Lib.CreateVehicle('T-RENT-011', 15000, Enum::"CGR Maintenance Strategy"::Default);
        ContractNo := Lib.CreateContract('T-RENT-011');

        // [WHEN] Checking out the contract
        asserterror RentalMgt.CheckOut(ContractNo);

        // [THEN] It fails because the vehicle is due for service
        Assert.ExpectedError('Vehicle T-RENT-011 is due for service.');
    end;

    [Test]
    procedure SwapToDueForServiceVehicleFailsAndContractUnchanged()
    var
        OldVehicle: Record "CGR Vehicle";
        NewVehicle: Record "CGR Vehicle";
        Contract: Record "CGR Rental Contract";
        RentalMgt: Codeunit "CGR Rental Mgt";
        ContractNo: Code[20];
    begin
        // [GIVEN] A checked-out contract on a vehicle that is not due for service, and
        // another vehicle that has reached its Default strategy's next service km
        Lib.CreateVehicle('T-RENT-012', 1000, Enum::"CGR Maintenance Strategy"::Default);
        Lib.CreateVehicle('T-RENT-013', 15000, Enum::"CGR Maintenance Strategy"::Default);
        ContractNo := Lib.CreateContract('T-RENT-012');
        RentalMgt.CheckOut(ContractNo);

        // [WHEN] Swapping the contract onto the vehicle that is due for service
        asserterror RentalMgt.SwapVehicle(ContractNo, 'T-RENT-013');

        // [THEN] It fails because the new vehicle is due for service
        Assert.ExpectedError('Vehicle T-RENT-013 is due for service.');

        // [THEN] The contract still points at the old vehicle
        Contract.Get(ContractNo);
        Assert.AreEqual('T-RENT-012', Contract."Vehicle No.", 'Swap must not move the contract when the new vehicle is due for service');

        // [THEN] Neither vehicle's checked-out flag changed
        OldVehicle.Get('T-RENT-012');
        Assert.IsTrue(OldVehicle."Checked Out", 'Old vehicle remains checked out');
        NewVehicle.Get('T-RENT-013');
        Assert.IsFalse(NewVehicle."Checked Out", 'New vehicle was never checked out');
    end;
}

