        // [THEN] The existing Suspend Rentals subscriber still makes it unavailable
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-014'), 'Suspend Rentals still blocks a vehicle not due for service');
    end;

    [Test]
    procedure SuspendRentalsCannotMakeDueVehicleAvailable()
    var
        Setup: Record "CGR Setup";
        FleetMgt: Codeunit "CGR Fleet Mgt";
    begin
        // [GIVEN] A vehicle that is due for service, neither checked out nor blocked
        Lib.CreateVehicle('T-FLT-015', 15000, Enum::"CGR Maintenance Strategy"::Default);
        Setup.GetOrCreate();

        // [WHEN] Suspend Rentals is on
        Setup."Suspend Rentals" := true;
        Setup.Modify();
        // [THEN] The vehicle is still not available
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-015'), 'Due vehicle is not available when Suspend Rentals is true');

        // [WHEN] Suspend Rentals is off
        Setup."Suspend Rentals" := false;
        Setup.Modify();
        // [THEN] The vehicle is still not available: the subscriber cannot override a due vehicle
        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-015'), 'Due vehicle is not available when Suspend Rentals is false');
    end;
}

