1	codeunit 70100 "CGR Fleet Mgt"
2	{
3	    procedure IsAvailable(VehicleNo: Code[20]): Boolean
4	    var
5	        Vehicle: Record "CGR Vehicle";
6	        Result: Boolean;
7	        IsHandled: Boolean;
8	    begin
9	        OnBeforeIsAvailable(VehicleNo, Result, IsHandled);
10	        if not IsHandled then
11	            if Vehicle.Get(VehicleNo) then
12	                Result := not Vehicle."Checked Out" and not Vehicle.Blocked
13	            else
14	                exit(false);
15	        exit(Result and not IsDueForService(VehicleNo));
16	    end;
17	
18	    procedure NextServiceKm(VehicleNo: Code[20]): Integer
19	    var
20	        Vehicle: Record "CGR Vehicle";
21	        Strategy: Interface "CGR Maintenance Strategy";
22	    begin
23	        Vehicle.Get(VehicleNo);
24	        Strategy := Vehicle.Strategy;
25	        exit(Strategy.NextServiceKm(Vehicle."Last Service Km"));
26	    end;
27	
28	    procedure IsDueForService(VehicleNo: Code[20]): Boolean
29	    var
30	        Vehicle: Record "CGR Vehicle";
31	        Strategy: Interface "CGR Maintenance Strategy";
32	    begin
33	        if not Vehicle.Get(VehicleNo) then
34	            exit(false);
35	        Strategy := Vehicle.Strategy;
36	        exit(Vehicle.Mileage >= Strategy.NextServiceKm(Vehicle."Last Service Km"));
37	    end;
38	
39	    [IntegrationEvent(false, false)]
40	    local procedure OnBeforeIsAvailable(VehicleNo: Code[20]; var Result: Boolean; var IsHandled: Boolean)
41	    begin
42	    end;
