1	codeunit 70200 "CGR Rental Mgt"
2	{
3	    var
4	        NotAvailableErr: Label 'Vehicle %1 is not available.', Comment = '%1 = vehicle number';
5	        DueForServiceErr: Label 'Vehicle %1 is due for service.', Comment = '%1 = vehicle number';
6	        WrongStatusErr: Label 'Rental contract %1 must have status %2.', Comment = '%1 = contract number, %2 = status';
7	        ReturnKmErr: Label 'Return km %1 is below the start km %2.', Comment = '%1 = return km, %2 = start km';
8	
9	    procedure CreateContract(VehicleNo: Code[20]; CustomerName: Text[100]; StartDate: Date; EndDate: Date): Code[20]
10	    var
11	        Contract: Record "CGR Rental Contract";
12	        Setup: Record "CGR Setup";
13	    begin
14	        Contract.Init();
15	        Contract."No." := Setup.NextContractNo();
16	        Contract."Vehicle No." := VehicleNo;
17	        Contract."Customer Name" := CustomerName;
18	        Contract."Start Date" := StartDate;
19	        Contract."End Date" := EndDate;
20	        Contract.Status := Contract.Status::Open;
21	        Contract.Insert(true);
22	        exit(Contract."No.");
23	    end;
24	
25	    procedure CheckOut(ContractNo: Code[20])
26	    var
27	        Contract: Record "CGR Rental Contract";
28	        Vehicle: Record "CGR Vehicle";
29	        FleetMgt: Codeunit "CGR Fleet Mgt";
30	        CoreEvents: Codeunit "CGR Core Events";
31	    begin
32	        Contract.Get(ContractNo);
33	        if Contract.Status <> Contract.Status::Open then
34	            Error(WrongStatusErr, ContractNo, Contract.Status::Open);
35	        if FleetMgt.IsDueForService(Contract."Vehicle No.") then
36	            Error(DueForServiceErr, Contract."Vehicle No.");
37	        if not FleetMgt.IsAvailable(Contract."Vehicle No.") then
38	            Error(NotAvailableErr, Contract."Vehicle No.");
39	        Vehicle.Get(Contract."Vehicle No.");
40	        Contract."Start Km" := Vehicle.Mileage;
41	        Contract.Status := Contract.Status::"Checked Out";
42	        Contract.Modify(true);
43	        CoreEvents.RaiseVehicleCheckedOut(Contract."Vehicle No.");
44	    end;
45	
46	    procedure SwapVehicle(ContractNo: Code[20]; NewVehicleNo: Code[20])
47	    var
48	        Contract: Record "CGR Rental Contract";
49	        OldVehicle: Record "CGR Vehicle";
50	        NewVehicle: Record "CGR Vehicle";
51	        FleetMgt: Codeunit "CGR Fleet Mgt";
52	    begin
53	        Contract.Get(ContractNo);
54	        if Contract.Status <> Contract.Status::"Checked Out" then
55	            Error(WrongStatusErr, ContractNo, Contract.Status::"Checked Out");
56	        NewVehicle.Get(NewVehicleNo);
57	        if FleetMgt.IsDueForService(NewVehicleNo) then
58	            Error(DueForServiceErr, NewVehicleNo);
59	        if NewVehicle."Checked Out" or NewVehicle.Blocked then
60	            Error(NotAvailableErr, NewVehicleNo);
61	        if OldVehicle.Get(Contract."Vehicle No.") then begin
62	            OldVehicle."Checked Out" := false;
63	            OldVehicle.Modify(true);
64	        end;
65	        NewVehicle."Checked Out" := true;
66	        NewVehicle.Modify(true);
67	        Contract."Vehicle No." := NewVehicleNo;
68	        Contract."Start Km" := NewVehicle.Mileage;
69	        Contract.Modify(true);
70	    end;
71	
72	    procedure Return(ContractNo: Code[20]; ReturnKm: Integer; DamageDescription: Text[100])
73	    var
74	        Contract: Record "CGR Rental Contract";
75	        CoreEvents: Codeunit "CGR Core Events";
76	    begin
77	        Contract.Get(ContractNo);
78	        if Contract.Status <> Contract.Status::"Checked Out" then
79	            Error(WrongStatusErr, ContractNo, Contract.Status::"Checked Out");
80	        if ReturnKm < Contract."Start Km" then
81	            Error(ReturnKmErr, Format(ReturnKm, 0, 9), Format(Contract."Start Km", 0, 9));
82	        Contract."Return Km" := ReturnKm;
83	        Contract."Damage Description" := DamageDescription;
84	        Contract.Status := Contract.Status::Returned;
85	        Contract.Modify(true);
86	        CoreEvents.RaiseVehicleReturned(Contract."Vehicle No.", ReturnKm, DamageDescription);
87	    end;
88	
89	    procedure Post(ContractNo: Code[20])
90	    var
91	        Contract: Record "CGR Rental Contract";
92	    begin
93	        Contract.Get(ContractNo);
94	        Codeunit.Run(Codeunit::"CGR Rental-Post", Contract);
95	    end;
96	}
